// 專屬放鬆/運動頻道：收到訊息或被加好友 → 回覆呼吸練習選單。
// 無可回覆對象時回傳空陣列，下游 LINE Reply 節點就不會執行。
// ⬇️ 把 LIFF_ID 換成你的 LIFF App ID（建立 LIFF 後取得）。
const LIFF_ID = 'YOUR_LIFF_ID';

const webhookItem = $input.first().json;
const events = (webhookItem.body && webhookItem.body.events) || [];

function liffButton(label, type, color) {
  return {
    type: 'button',
    style: 'primary',
    color,
    height: 'sm',
    margin: 'sm',
    action: { type: 'uri', label, uri: 'https://liff.line.me/' + LIFF_ID + '?type=' + type },
  };
}

function buildMenu(replyToken, intro) {
  const bubble = {
    type: 'bubble',
    body: {
      type: 'box',
      layout: 'vertical',
      spacing: 'md',
      contents: [
        { type: 'text', text: '來做個呼吸練習 🌿', weight: 'bold', size: 'lg' },
        { type: 'text', text: intro, size: 'sm', color: '#888888', wrap: true },
        liffButton('4-7-8 呼吸法', '478', '#6F8BF0'),
        liffButton('箱式呼吸法', 'box', '#5FA8A6'),
        liffButton('腹式呼吸', 'belly', '#8F76C9'),
        liffButton('正念呼吸', 'mindful', '#C99A6B')
      ]
    }
  };
  return { replyToken, messages: [{ type: 'flex', altText: '來做個呼吸練習 🌿', contents: bubble }] };
}

const out = [];
for (const event of events) {
  if (!event.replyToken) continue;
  if (event.type === 'follow') {
    out.push({ json: { replyBody: buildMenu(event.replyToken, '歡迎～需要放鬆或想動一動時，隨時選一種節奏跟著呼吸。') } });
  } else if (event.type === 'message') {
    out.push({ json: { replyBody: buildMenu(event.replyToken, '選一種節奏，跟著畫面一起呼吸，幾分鐘就能放鬆下來。') } });
  }
}

return out;
